-- Public job identifier: `jobId` is what links (`/jobs/<jobId>`) and the
-- single-job API routes use; the UUID primary key stays internal.
-- 16 lowercase hex characters (64 random bits) generated by the database,
-- so every insert path gets one. The volatile default is evaluated per row,
-- which also gives every existing job its own id.

-- AlterTable
ALTER TABLE "jobs"
ADD COLUMN "jobId" TEXT NOT NULL DEFAULT substr(md5((gen_random_uuid())::text), 1, 16);

-- CreateIndex
CREATE UNIQUE INDEX "jobs_jobId_key" ON "jobs"("jobId");
